mapper.select:
SELECT FINPROD_NAME text, FINPROD_ID id FROM FIN_PRODUCT
and FINPROD_MARKET_ID like concat(concat('%',#{search}),'%')
AND FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR}

SELECT FINPROD_NAME text, FINPROD_ID id FROM FIN_PRODUCT
AND FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR}
and (FINPROD_NAME like concat(concat('%',#{search}),'%') or FINPROD_ID like concat(concat('%',#{search}),'%'))

SELECT T1.FINPROD_ID, T1.FINPROD_NAME, T1.FINPROD_MARKET_ID, T1.VDATE, T1.MDATE, T1.MANAGER, T1.TRUSTEE_ID, T3.PROD_REGIST_CODE, T3.PAY_TYPE, T3.COLLECT_TYPE,
T4.VAT_TAX_RATE*100 vatTaxRate, T4.ADT_TAX_RATE*100 adtTaxRate,
T2.ACCT_NO busiAcctNo, T2.ACCT_NO oldBusiAcctNo, T1.CALENDAR_ID FROM FIN_PRODUCT T1 left join STL_FIN_PRODUCT_ACCT T2 ON T2.FINPROD_ID = T1.FINPROD_ID
AND T2.ACCT_TYPE = #{acctType}
AND T2.CCY = #{ccy}
left join FIN_PRODUCT_ADD T3 ON T3.FINPROD_ID = T1.FINPROD_ID
left join PA_FIN_PRODUCT T4 on T1.FINPROD_ID = T4.FINPROD_ID
and T1.FINPROD_ID = #{finprodId}

select
count(1)
from TRD_PRODUCT_DEAL
where CHL_ID = #{finprodId,jdbcType=VARCHAR}
AND IS_CANCEL=#{NO} AND TRADE_STATUS=#{TRADE_STATUS01}

	SELECT count(s.acct_no)
  	FROM FIN_PRODUCT T, STL_FIN_PRODUCT_ACCT S
 	WHERE T.FINPROD_ID = S.FINPROD_ID

			AND (T.FINPROD_TYPE2 = #{F28,jdbcType=VARCHAR} OR T.FINPROD_TYPE2 = #{F16,jdbcType=VARCHAR})


			AND T.FINPROD_TYPE2 = #{F28,jdbcType=VARCHAR}


			AND T.FINPROD_MARKET_ID != #{finprodMarketId,jdbcType=VARCHAR}

		AND S.ACCT_NO = #{busiAcctNo,jdbcType=VARCHAR}
